 import React, { useEffect, useState } from 'react';
+import { useParams, useNavigate } from 'react-router-dom';
+import styled from 'styled-components';
+import { useChatStore } from '@/store/chatStore';
+import { getChatSession, getChatMessages } from '@/lib/api/user/userApi';
+import { useToast } from '@/components/common/ToastProvider';

+const SharePageWrapper = styled.div`
+  min-height: 100vh;
+  background-color: ${({ theme }) => theme.body};
+  display: flex;
+  flex-direction: column;
+  align-items: center;
+  justify-content: center;
+  padding: 20px;
+`;
+
+const LoadingContainer = styled.div`
+  text-align: center;
+  color: ${({ theme }) => theme.text};
+`;
+
+const LoadingSpinner = styled.div`
+  width: 40px;
+  height: 40px;
+  border: 4px solid ${({ theme }) => theme.border};
+  border-top: 4px solid ${({ theme }) => theme.accent};
+  border-radius: 50%;
+  animation: spin 1s linear infinite;
+  margin: 0 auto 20px;
+
+  @keyframes spin {
+    0% { transform: rotate(0deg); }
+    100% { transform: rotate(360deg); }
+  }
+`;
+
+const ErrorContainer = styled.div`
+  text-align: center;
+  color: #d32f2f;
+  max-width: 400px;
+`;
+
+const ErrorIcon = styled.div`
+  font-size: 48px;
+  margin-bottom: 16px;
+`;
+
+const ErrorTitle = styled.h2`
+  margin: 0 0 8px 0;
+  font-size: 20px;
+  font-weight: 600;
+`;
+
+const ErrorMessage = styled.p`
+  margin: 0 0 24px 0;
+  font-size: 14px;
+  line-height: 1.5;
+  color: ${({ theme }) => theme.subtleText};
+`;
+
+const RetryButton = styled.button`
+  background: ${({ theme }) => theme.accent};
+  color: white;
+  border: none;
+  padding: 12px 24px;
+  border-radius: 8px;
+  font-size: 14px;
+  font-weight: 500;
+  cursor: pointer;
+  transition: opacity 0.2s;
+
+  &:hover {
+    opacity: 0.8;
+  }
+`;
+
+const BackButton = styled.button`
+  background: transparent;
+  color: ${({ theme }) => theme.text};
+  border: 1px solid ${({ theme }) => theme.border};
+  padding: 12px 24px;
+  border-radius: 8px;
+  font-size: 14px;
+  font-weight: 500;
+  cursor: pointer;
+  margin-left: 12px;
+  transition: background-color 0.2s;
+
+  &:hover {
+    background-color: ${({ theme }) => theme.surface1};
+  }
+`;
+
+const SharePage: React.FC = () => {
+  const { sessionId } = useParams<{ sessionId: string }>();
+  const navigate = useNavigate();
+  const { error, success } = useToast();
+  const { setChatSessionId, addMessage } = useChatStore();
+  
+  const [loading, setLoading] = useState(true);
+  const [errorMessage, setErrorMessage] = useState<string | null>(null);
+
+  useEffect(() => {
+    const loadSharedSession = async () => {
+      if (!sessionId) {
+        setErrorMessage('세션 ID가 없습니다.');
+        setLoading(false);
+        return;
+      }
+
+      try {
+        console.log('공유 세션 로딩 중:', sessionId);
+        
+        // 세션 정보 가져오기
+        const sessionResponse = await getChatSession(sessionId);
+        
+        if (sessionResponse && sessionResponse.statusCode === 200 && sessionResponse.data) {
+          const sessionData = sessionResponse.data;
+          console.log('세션 데이터:', sessionData);
+          
+          // 채팅 스토어에 세션 ID 설정
+          setChatSessionId(sessionData._id);
+          
+          // 세션의 메시지들 가져오기
+          try {
+            const messagesResponse = await getChatMessages(sessionId);
+            
+            if (messagesResponse && messagesResponse.statusCode === 200 && messagesResponse.data) {
+              const messages = messagesResponse.data;
+              console.log('메시지 데이터:', messages);
+              
+              // 메시지들을 채팅 스토어에 추가
+              messages.forEach(message => {
+                addMessage({
+                  role: message.role.toLowerCase() as 'user' | 'ai',
+                  content: message.content.value
+                });
+              });
+            } else {
+              console.warn('메시지를 가져올 수 없습니다.');
+            }
+          } catch (messagesError) {
+            console.warn('메시지 로딩 실패:', messagesError);
+          }
+          
+          success('공유된 채팅 세션이 로드되었습니다.');
+          
+          // AI 채팅 페이지로 이동
+          const { companyCode } = useParams();
+          navigate(`/aiclient/${companyCode}/ai`);
+          
+        } else {
+          throw new Error(sessionResponse?.error?.message || '세션을 찾을 수 없습니다.');
+        }
+        
+      } catch (err) {
+        console.error('세션 로딩 실패:', err);
+        setErrorMessage('공유된 채팅 세션을 불러올 수 없습니다. 세션이 삭제되었거나 접근 권한이 없을 수 있습니다.');
+        setLoading(false);
+      }
+    };
+
+    loadSharedSession();
+  }, [sessionId, navigate, setChatSessionId, addMessage, success, error]);
+
+  const handleRetry = () => {
+    setLoading(true);
+    setErrorMessage(null);
+    // 페이지 새로고침
+    window.location.reload();
+  };
+
+  const handleBack = () => {
+    const { companyCode } = useParams();
+    navigate(`/aiclient/${companyCode}/ai`);
+  };
+
+  if (loading) {
+    return (
+      <SharePageWrapper>
+        <LoadingContainer>
+          <LoadingSpinner />
+          <p>공유된 채팅 세션을 불러오는 중...</p>
+        </LoadingContainer>
+      </SharePageWrapper>
+    );
+  }
+
+  if (errorMessage) {
+    return (
+      <SharePageWrapper>
+        <ErrorContainer>
+          <ErrorIcon>⚠️</ErrorIcon>
+          <ErrorTitle>세션을 불러올 수 없습니다</ErrorTitle>
+          <ErrorMessage>{errorMessage}</ErrorMessage>
+          <div>
+            <RetryButton onClick={handleRetry}>다시 시도</RetryButton>
+            <BackButton onClick={handleBack}>돌아가기</BackButton>
+          </div>
+        </ErrorContainer>
+      </SharePageWrapper>
+    );
+  }
+
+  return null;
+};
+
+export default SharePage;

