+            <p>공유된 채팅 세션을 불러오는 중...</p>
+          </LoadingContainer>
+        </Container>
+      </LayoutWrapper>
+    );
+  }
+
+  if (errorMessage) {
+    return (
+      <LayoutWrapper>
+        <TopNav>
+          <div className="left-icons">
+            <Icon 
+              src={isDarkMode ? '/ai-estimate/arrow_back.png' : '/ai-estimate/arrow_back.png'} 
+              width={24} 
+              height={24} 
+              onClick={handleBack}
+            />
+          </div>
+          <NavTitle>공유된 채팅</NavTitle>
+          <div className="right-icons"></div>
+        </TopNav>
+        <Container>
+          <ErrorContainer>
+            <ErrorIcon>⚠️</ErrorIcon>
+            <ErrorTitle>세션을 불러올 수 없습니다</ErrorTitle>
+            <ErrorMessage>{errorMessage}</ErrorMessage>
+            <div>
+              <RetryButton onClick={handleRetry}>다시 시도</RetryButton>
+              <BackButton onClick={handleBack}>돌아가기</BackButton>
+            </div>
+          </ErrorContainer>
+        </Container>
+      </LayoutWrapper>
+    );
+  }
+
+  return (
+    <LayoutWrapper>
+      <TopNav>
+        <div className="left-icons">
+          <Icon 
+            src={isDarkMode ? '/ai-estimate/arrow_back.png' : '/ai-estimate/arrow_back.png'} 
+            width={24} 
+            height={24} 
+            onClick={handleBack}
+          />
+        </div>
+        <NavTitle>공유된 채팅</NavTitle>
+        <div className="right-icons"></div>
+      </TopNav>
+      
+      <Container>
+        <ReadOnlyNotice>
