+        </ReadOnlyNotice>
+        
+        <ChatBox>
+          {messages.map((message, index) => (
+            <div key={index}>
+              {message.role === 'user' ? (
+                <UserMessage>{message.content}</UserMessage>
+              ) : (
+                <AiResponseMessage 
+                  content={message.content}
+                />
+              )}
+            </div>
+          ))}
+        </ChatBox>
+      </Container>
+
+
+    </LayoutWrapper>
+  );
+};
+
+export default SharePage;

