+  font-size: 20px;
+  font-weight: 600;
+`;
+
+const ErrorMessage = styled.p`
+  margin: 0 0 24px 0;
+  font-size: 14px;
+  line-height: 1.5;
+  color: ${({ theme }) => theme.subtleText};
+`;
+
+const RetryButton = styled.button`
+  background: ${({ theme }) => theme.accent};
+  color: white;
+  border: none;
+  padding: 12px 24px;
+  border-radius: 8px;
